import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import './HomePage.css';

export default function HomePage() {
  const [students, setStudents] = useState([]);

  useEffect(() => {
    const fetchStudents = async () => {
      try {
        const response = await fetch('http://localhost:5000/api/students');
        const data = await response.json();
        setStudents(data);
      } catch (error) {
        console.error('Error fetching students:', error);
      }
    };
    fetchStudents();
  }, []);

  const studentDetails = [
    {
      id: 1,
      rollNumber: 'CS001',
      name: 'John Doe',
      email: 'john.doe@example.com',
      department: 'Computer Science'
    },
    {
      id: 2,
      rollNumber: 'ME001',
      name: 'Jane Smith',
      email: 'jane.smith@example.com',
      department: 'Mechanical Engineering'
    },
    {
      id: 3,
      rollNumber: 'EE001',
      name: 'Mike Johnson',
      email: 'mike.johnson@example.com',
      department: 'Electrical Engineering'
    },
    {
      id: 4,
      rollNumber: 'CE001',
      name: 'Sarah Wilson',
      email: 'sarah.wilson@example.com',
      department: 'Civil Engineering'
    }
  ];

  return (
    <div className="dashboard-container">
      <div className="sidebar">
        <nav>
          <ul>
            <li>
              <Link to="/"><i className="fas fa-home"></i> Dashboard</Link>
            </li>
            <li>
              <Link to="/students"><i className="fas fa-user-graduate"></i> Student Section</Link>
            </li>
            <li>
              <Link to="/faculty"><i className="fas fa-chalkboard-teacher"></i> Faculty</Link>
            </li>
            <li>
              <Link to="/courses"><i className="fas fa-book"></i> Courses</Link>
            </li>
            <li>
              <Link to="/attendance"><i className="fas fa-clipboard-check"></i> Attendance</Link>
            </li>
            <li>
              <Link to="/grades"><i className="fas fa-graduation-cap"></i> Grades</Link>
            </li>
          </ul>
        </nav>
      </div>
      <div className="main-content">
        <h1 className="text-center mb-4">Student Details</h1>
        <div className="students-container">
          {students.map(student => (
            <div key={student.id} className="student-card">
              <div className="card-header">
                <h3>{student.name}</h3>
                <span className="roll-number">{student.rollNumber}</span>
              </div>
              <div className="card-body">
                <div className="student-info">
                  <p><strong>Email:</strong> {student.email}</p>
                  <p><strong>Department:</strong> {student.department}</p>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
